// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createItem, createFlow, triggerFlow, deleteFlow, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const collections = "tasks";

    const collectionsPostResponse = await createCollection(client, headers, collections);
    expect(getResponseValue(collectionsPostResponse, "data.collection"), 'collection').toBe("tasks");

    const itemsPostResponse = await createItem(client, headers, collections, "Reminder task", "2026-08-29T00:30:00Z");
    expect(getResponseValue(itemsPostResponse, "data.title"), 'title').toBe("Reminder task");
    expect(getResponseValue(itemsPostResponse, "data.due_at"), 'due_at').toMatch(/^2026-08-29T00:30:00/);
    expect(getResponseValue(itemsPostResponse, "data.id"), 'id').toBeGreaterThan(0);

    const flowsPostResponse = await createFlow(client, headers, "Hourly task reminders", "active");
    expect(getResponseValue(flowsPostResponse, "data.name"), 'name').toBe("Hourly task reminders");
    expect(getResponseValue(flowsPostResponse, "data.status"), 'status').toBe("active");
    expect(getResponseValue(flowsPostResponse, "data.trigger"), 'trigger').toBe("schedule");
    expect(getResponseValue(flowsPostResponse, "data.id"), 'id').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

    const triggerPostResponse = await triggerFlow(client, headers, getResponseValue(flowsPostResponse, "data.id"), "2026-08-28T22:15:00Z");
    expect(getResponseValue(triggerPostResponse, "data.executed"), 'executed').toBe(true);
    expect(getResponseValue(triggerPostResponse, "data.execution_id"), 'execution_id').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getResponseValue(triggerPostResponse, "data.webhook_count"), 'webhook_count').toBe(1);

    const triggerPost1Response = await triggerFlow(client, headers, getResponseValue(flowsPostResponse, "data.id"), "2026-08-28T22:45:00Z");
    expect(getResponseValue(triggerPost1Response, "data.executed"), 'executed').toBe(true);
    expect(getResponseValue(triggerPost1Response, "data.webhook_count"), 'webhook_count').toBe(0);

    const flowsFlowsDeleteResponse = await deleteFlow(client, headers, getResponseValue(flowsPostResponse, "data.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collections);
});
